<?php namespace App\Services;
final class UploadService{public function store(array $f):array{if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new \InvalidArgumentException('Unggahan gagal.');if(($f['size']??0)>((int)env('UPLOAD_MAX_MB','4'))*1048576)throw new \InvalidArgumentException('File terlalu besar.');$info=@getimagesize($f['tmp_name']);$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!$info||!isset($map[$mime])||$info[0]>5000||$info[1]>5000)throw new \InvalidArgumentException('Hanya gambar JPEG, PNG, atau WebP yang valid (maks. 5000 px).');$name=bin2hex(random_bytes(20)).'.'.$map[$mime];if(!move_uploaded_file($f['tmp_name'],ROOT.'/public/uploads/'.$name))throw new \RuntimeException('Gagal menyimpan file.');return ['filename'=>$name,'mime'=>$mime,'size'=>$f['size'],'width'=>$info[0],'height'=>$info[1]];}}
